import React, { type FormEvent, forwardRef, useState } from 'react';
import styled from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Typography from '@dynatrace/strato-design-tokens/typography';

import { ButtonGroupContext } from './contexts/ButtonGroupContext.js';
import type {
  RadioGroupState,
  ToggleButtonGroupItemProps,
  ToggleButtonGroupProps,
} from './types.js';
import { _useControllableState } from '../../core/hooks/useControllableState.js';
import type { RadioGroupBaseProps } from '../../forms/radio/RadioGroup.js';

//#region Typings
export interface ValueBase<T, C = T> {
  value?: T;
  defaultValue?: T;
  onChange?: (value: C) => void;
}

export interface ToggleRadioGroupProps
  extends RadioGroupBaseProps,
    ValueBase<string> {}

interface ToggleButtonGroupElementProps {
  /** The props of an item in the ToggleButtonGroup */
  props: ToggleButtonGroupItemProps;
}
//#endregion

//#region Styled Components
// FIXME:  Move to pure styled components and object notation
const StyledToggleButtonGroup = styled.div`
  font-family: ${Typography.Text.Base.Emphasized.Family};
  font-size: ${Typography.Text.Base.Emphasized.Size};
  font-weight: ${Typography.Text.Base.Emphasized.Weight};
  background: ${Colors.Background.Container.Neutral.Default};
  border-radius: ${Borders.Radius.Field.Default};
  display: inline-flex;
`;
//#endregion

/**
 * The `ToggleButtonGroup` is used to group related options.
 * The group consists of at least two `ToggleButtonGroupItems`.
 * The `ToggleButtonGroup` supports exclusive selection only.
 * That means that selecting one option deselects any other.
 */
export const ToggleButtonGroup = forwardRef<
  HTMLDivElement,
  ToggleButtonGroupProps
>((props, forwardedRef) => {
  const {
    children,
    disabled: isDisabled = false,
    required: isRequired = false,
    readOnly: isReadOnly = false,
    value,
    defaultValue,
    name,
    onChange,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  }: ToggleButtonGroupProps = props;

  const radioGroupProps: ToggleRadioGroupProps = {
    children,
    id: name,
    disabled: isDisabled,
    name,
    value,
    defaultValue,
    onChange,
    ...remainingProps,
  };

  const radioValue =
    radioGroupProps.value !== undefined && radioGroupProps.value.length > 0
      ? value
      : undefined;

  const [selectedValue, setSelectedValue] = _useControllableState({
    defaultValue,
    value: radioValue,
  });

  const [selectedIsDisabled, setSelectedIsDisabled] = React.useState(false);
  const [firstFocusableValue, setFirstFocusableValue] = useState<string | null>(
    null,
  );

  const radioFocusDefaultValue =
    defaultValue !== undefined ? defaultValue : firstFocusableValue;

  const [lastFocusedValue, setLastFocusedValue] = _useControllableState({
    defaultValue: radioFocusDefaultValue,
    value: radioValue,
  });

  const mappedChildren = React.Children.map(children, (child) => child);

  React.useEffect(() => {
    let firstFocusable: string | null = null;

    mappedChildren?.forEach((child) => {
      const item = (child as ToggleButtonGroupElementProps).props;

      // Find the first item that should be focused if no item is selected.
      if (firstFocusable === null && !item.disabled) {
        firstFocusable = item.value;
        if (firstFocusable !== firstFocusableValue) {
          setFirstFocusableValue(firstFocusable);
        }
      }
      // Check if the selected item is disabled.
      if (selectedValue === item.value) {
        if (item.disabled) {
          setSelectedIsDisabled(true);
        } else if (selectedIsDisabled) {
          setSelectedIsDisabled(false);
        }
      }
    });
  }, [firstFocusableValue, mappedChildren, selectedIsDisabled, selectedValue]);

  const state: RadioGroupState = {
    id: name,
    isDisabled,
    isReadOnly,
    isRequired,
    selectedValue,
    setSelectedValue,
    lastFocusedValue,
    setLastFocusedValue,
    firstFocusableValue,
    selectedIsDisabled,
  };

  const handleChange = (
    value: string,
    event?: FormEvent<HTMLElement | SVGElement>,
  ) => {
    if (!event) {
      return;
    }

    onChange?.(value, event);
  };

  return (
    <StyledToggleButtonGroup
      data-testid={dataTestId}
      ref={forwardedRef}
      role="radiogroup"
      aria-orientation="horizontal"
      className={consumerClassName}
      style={consumerStyle}
      {...remainingProps}
    >
      <ButtonGroupContext.Provider
        value={{ state: { ...state, onChange: handleChange } }}
      >
        {children}
      </ButtonGroupContext.Provider>
    </StyledToggleButtonGroup>
  );
});
